// Due for attempt?: pass one item when the claimer may try now: not claimed, not stopped, and the wait since the last attempt has passed.
const data = $getWorkflowStaticData('global');
// The settings this attempt runs with (no secrets). A stop is for the settings in force when it happened,
// so changing them (or a stop recorded before settings were tracked) starts the claimer again.
// The leading tag is part of the key: bump it when a code change should lift stops recorded under the old code.
const config = ['claimer-2', 'HUNTER_OCI_API_BASE', 'HUNTER_OCI_TENANCY_OCID', 'HUNTER_OCI_USER_OCID', 'HUNTER_OCI_KEY_FINGERPRINT',
  'HUNTER_OCI_COMPARTMENT_OCID', 'HUNTER_OCI_AVAILABILITY_DOMAIN', 'HUNTER_OCI_SUBNET_OCID', 'HUNTER_OCI_IMAGE_OCID',
  'HUNTER_OCI_SSH_PUBLIC_KEY', 'HUNTER_OCI_A1_OCPUS', 'HUNTER_OCI_A1_MEMORY_GB'].map((name) => $env[name] ?? '').join('|');
if (data.stopped && data.config !== config) delete data.stopped;
if (data.claimed || data.stopped || Date.now() < (data.nextAttemptAt ?? 0)) return [];
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const counters = metrics.counters ?? {};
const lifetime = data.lifetime ?? {};
counters.dueChecks = (counters.dueChecks ?? 0) + 1;
lifetime.dueChecks = (lifetime.dueChecks ?? 0) + 1;
data.metrics = { ...metrics, counters };
data.lifetime = lifetime;
data.config = config;
// Hold the claimer while this attempt runs, so a run that starts meanwhile cannot launch a second instance.
data.nextAttemptAt = Date.now() + 15 * 60 * 1000;
return [{ json: { due: true } }];

// Cost guard: count the A1 instances and the boot and block volumes that exist, and refuse the launch unless the request still fits the Always Free limits.
// Also reconciles pending/unknown launches via read-only GETs before allowing any new launch.
// A list request that fails, or runs past MAX_PAGES, is a refusal too: an unknown total is not a free total.
// A failure that passes by itself (no answer, HTTP 429 or 5xx) only skips this attempt and preserves active cooldown.
const crypto = require('crypto');
const helpers = this.helpers;

const LIMIT_OCPUS = 4;
const LIMIT_MEMORY_GB = 24;
const LIMIT_STORAGE_GB = 200;
const MAX_PAGES = 100;
const rawOcpus = $env.HUNTER_OCI_A1_OCPUS;
const rawMem = $env.HUNTER_OCI_A1_MEMORY_GB;
const ocpus = rawOcpus ? Number(rawOcpus) : 4;
const memoryInGBs = rawMem ? Number(rawMem) : 24;
const REQUEST = { shape: 'VM.Standard.A1.Flex', ocpus, memoryInGBs, bootVolumeSizeInGBs: 50, displayName: 'vm-hunter-a1' };

const base = $env.HUNTER_OCI_API_BASE;
// The Code node sandbox has no URL global, so take the host from the base URL by hand.
const host = base.replace(/^https?:\/\//, '').split('/')[0];
const keyId = [$env.HUNTER_OCI_TENANCY_OCID, $env.HUNTER_OCI_USER_OCID, $env.HUNTER_OCI_KEY_FINGERPRINT].join('/');
// The PEM may arrive with literal \n sequences when it is set as one line in the environment.
const key = $env.HUNTER_OCI_PRIVATE_KEY_PEM.replace(/\\n/g, '\n');
const compartment = encodeURIComponent($env.HUNTER_OCI_COMPARTMENT_OCID);
const domain = encodeURIComponent($env.HUNTER_OCI_AVAILABILITY_DOMAIN);

function parseRetryAfter(val) {
  if (val === undefined || val === null || val === '') return 0;
  const num = Number(val);
  if (Number.isFinite(num) && num >= 0) return Math.ceil(num);
  const parsed = Date.parse(String(val));
  if (Number.isFinite(parsed)) return Math.max(0, Math.ceil((parsed - Date.now()) / 1000));
  return 0;
}

// Signed GET (OCI HTTP signatures): the signing string covers the request target, the date and the host.
function signedGet(target) {
  const date = new Date().toUTCString();
  const signing = [`(request-target): get ${target}`, `date: ${date}`, `host: ${host}`].join('\n');
  const signature = crypto.sign('sha256', Buffer.from(signing), key).toString('base64');
  return { date, authorization: `Signature version="1",keyId="${keyId}",algorithm="rsa-sha256",headers="(request-target) date host",signature="${signature}"` };
}

// Every page of one list request, as one array. Throws on any failure, marked transient when retrying can fix it.
async function listAll(path) {
  const items = [];
  let page = '';
  for (let pages = 0; pages < MAX_PAGES; pages++) {
    const target = page ? `${path}&page=${encodeURIComponent(page)}` : path;
    let response;
    try {
      response = await helpers.httpRequest({ method: 'GET', url: base + target, headers: signedGet(target), timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    } catch (error) {
      error.transient = true;
      throw error;
    }
    if (response.statusCode !== 200) {
      const error = new Error(`${path.split('?')[0]} returned HTTP ${response.statusCode}`);
      error.statusCode = response.statusCode;
      error.retryAfter = parseRetryAfter(response.headers?.['retry-after']);
      error.transient = response.statusCode === 429 || response.statusCode >= 500;
      throw error;
    }
    const list = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
    items.push(...list);
    page = response.headers['opc-next-page'] ?? '';
    if (!page) return items;
  }
  throw new Error(`${path.split('?')[0]} has more than ${MAX_PAGES} pages`);
}

const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const counters = metrics.counters ?? {};
const lifetime = data.lifetime ?? {};
const rateLimit = data.rateLimit ?? {
  consecutive429: metrics.consecutive429 ?? 0,
  backoffLevel: Math.min(5, metrics.consecutive429 ?? 0),
  non429Streak: 0,
  currentWaitSeconds: metrics.currentWaitSeconds ?? 60,
};

function inc(name) {
  counters[name] = (counters[name] ?? 0) + 1;
  lifetime[name] = (lifetime[name] ?? 0) + 1;
}

function handleTransient(error) {
  let wait = Math.max(60, rateLimit.currentWaitSeconds ?? 60);
  if (error.statusCode === 429) {
    inc('rateLimited');
    rateLimit.consecutive429 = (rateLimit.consecutive429 ?? 0) + 1;
    rateLimit.backoffLevel = Math.min(5, (rateLimit.backoffLevel ?? 0) + 1);
    rateLimit.non429Streak = 0;
    const backoff = Math.min(900, 60 * 2 ** (rateLimit.backoffLevel - 1));
    wait = Math.max(backoff, error.retryAfter || 0);
  } else {
    inc('errors');
  }
  rateLimit.currentWaitSeconds = wait;
  data.rateLimit = rateLimit;
  metrics.consecutive429 = rateLimit.consecutive429;
  metrics.currentWaitSeconds = wait;
  data.metrics = { ...metrics, counters };
  data.lifetime = lifetime;
  data.nextAttemptAt = Date.now() + wait * 1000;
  return [];
}

// Reconcile pendingInstance (PROVISIONING) or pendingLaunch (timeout/unknown) before any new launch.
if (data.pendingInstance || data.pendingLaunch) {
  inc('costGuardChecks');
  let instances;
  try {
    instances = await listAll(`/20160918/instances?compartmentId=${compartment}`);
  } catch (error) {
    if (error.transient) return handleTransient(error);
    data.stopped = true;
    inc('costGuardRefusals');
    data.metrics = { ...metrics, counters };
    data.lifetime = lifetime;
    return [{ json: { kind: 'failure', title: 'Cost guard refused the A1 launch', body: `could not list existing resources: ${error.message}\nThe claimer has stopped.`, url: '' } }];
  }

  if (data.pendingInstance) {
    const inst = instances.find((i) => i.id === data.pendingInstance.id);
    if (inst && inst.lifecycleState === 'RUNNING') {
      const claimedAt = data.pendingInstance.acceptedAt || new Date().toISOString();
      delete data.pendingInstance;
      data.claimed = { id: inst.id, claimedAt, verifiedAt: new Date().toISOString(), lifecycleState: 'RUNNING' };
      inc('success');
      inc('verifiedRunning');
      data.metrics = { ...metrics, counters };
      data.lifetime = lifetime;
      const totalAttempts = lifetime.attempts ?? counters.attempts ?? 0;
      return [{ json: { skipLaunch: true, outcome: 'claimed', kind: 'claim', title: `A1 VM created: ${inst.displayName || REQUEST.displayName}`, body: `Instance ${inst.id}\n${inst.shape}, ${inst.shapeConfig?.ocpus} OCPU, ${inst.shapeConfig?.memoryInGBs} GB\nAttempts: ${totalAttempts}`, url: '' } }];
    }
    if (inst && !['TERMINATED', 'TERMINATING'].includes(inst.lifecycleState)) {
      data.pendingInstance.lifecycleState = inst.lifecycleState;
      rateLimit.currentWaitSeconds = 60;
      data.rateLimit = rateLimit;
      data.nextAttemptAt = Date.now() + 60 * 1000;
      data.metrics = { ...metrics, counters };
      data.lifetime = lifetime;
      return [];
    }
    const oldId = data.pendingInstance.id;
    const state = inst ? inst.lifecycleState : 'NOT_FOUND';
    delete data.pendingInstance;
    inc('terminalFailures');
    const wait = Math.max(60, rateLimit.currentWaitSeconds ?? 60);
    data.nextAttemptAt = Date.now() + wait * 1000;
    data.metrics = { ...metrics, counters };
    data.lifetime = lifetime;
    return [{ json: { skipLaunch: true, outcome: 'terminal_failure', kind: 'alert', title: 'A1 instance failed during provisioning', body: `Instance ${oldId} ended in state ${state}. Resuming hunt.`, url: '' } }];
  }

  // Reconcile pendingLaunch (response lost after timeout)
  const known = new Set(data.pendingLaunch.knownInstanceIds ?? []);
  const submittedAt = data.pendingLaunch.submittedAt || new Date().toISOString();
  const found = instances.find((i) => i.shape === REQUEST.shape && i.lifecycleState !== 'TERMINATED' && !known.has(i.id));
  delete data.pendingLaunch;
  if (found && found.lifecycleState === 'RUNNING') {
    data.claimed = { id: found.id, claimedAt: submittedAt, verifiedAt: new Date().toISOString(), lifecycleState: 'RUNNING' };
    inc('acceptedLaunches');
    inc('success');
    inc('verifiedRunning');
    data.metrics = { ...metrics, counters };
    data.lifetime = lifetime;
    const totalAttempts = lifetime.attempts ?? counters.attempts ?? 0;
    return [{ json: { skipLaunch: true, outcome: 'claimed', kind: 'claim', title: `A1 VM created: ${found.displayName || REQUEST.displayName}`, body: `Instance ${found.id}\n${found.shape}, ${found.shapeConfig?.ocpus} OCPU, ${found.shapeConfig?.memoryInGBs} GB\nAttempts: ${totalAttempts}`, url: '' } }];
  }
  if (found) {
    data.pendingInstance = { id: found.id, displayName: found.displayName || REQUEST.displayName, shape: found.shape, shapeConfig: found.shapeConfig, acceptedAt: submittedAt, lifecycleState: found.lifecycleState };
    inc('acceptedLaunches');
    data.nextAttemptAt = Date.now() + 60 * 1000;
    data.metrics = { ...metrics, counters };
    data.lifetime = lifetime;
    return [];
  }
  const wait = Math.max(60, rateLimit.currentWaitSeconds ?? 60);
  data.nextAttemptAt = Date.now() + wait * 1000;
  data.metrics = { ...metrics, counters };
  data.lifetime = lifetime;
  return [];
}

inc('costGuardChecks');
const problems = [];
let used = '';
let knownInstanceIds = [];
try {
  if (!Number.isFinite(REQUEST.ocpus) || REQUEST.ocpus <= 0) problems.push(`invalid OCPUs: ${rawOcpus}`);
  if (!Number.isFinite(REQUEST.memoryInGBs) || REQUEST.memoryInGBs <= 0) problems.push(`invalid memoryInGBs: ${rawMem}`);
  const instances = await listAll(`/20160918/instances?compartmentId=${compartment}`);
  const bootVolumes = await listAll(`/20160918/bootVolumes?compartmentId=${compartment}&availabilityDomain=${domain}`);
  const blockVolumes = await listAll(`/20160918/volumes?compartmentId=${compartment}`);

  const a1 = instances.filter((i) => i.shape === REQUEST.shape && i.lifecycleState !== 'TERMINATED');
  knownInstanceIds = a1.map((i) => i.id);
  const usedOcpus = a1.reduce((sum, i) => sum + (i.shapeConfig?.ocpus ?? 0), 0);
  const usedMemory = a1.reduce((sum, i) => sum + (i.shapeConfig?.memoryInGBs ?? 0), 0);
  const usedStorage = [...bootVolumes, ...blockVolumes]
    .filter((v) => !['TERMINATED', 'TERMINATING'].includes(v.lifecycleState))
    .reduce((sum, v) => sum + (v.sizeInGBs ?? 0), 0);
  used = `Existing: ${usedOcpus} OCPU, ${usedMemory} GB memory, ${usedStorage} GB storage.`;

  if (REQUEST.shape !== 'VM.Standard.A1.Flex') problems.push(`shape ${REQUEST.shape} is not free`);
  if (usedOcpus + REQUEST.ocpus > LIMIT_OCPUS) problems.push(`OCPUs would be ${usedOcpus + REQUEST.ocpus}, the limit is ${LIMIT_OCPUS}`);
  if (usedMemory + REQUEST.memoryInGBs > LIMIT_MEMORY_GB) problems.push(`memory would be ${usedMemory + REQUEST.memoryInGBs} GB, the limit is ${LIMIT_MEMORY_GB} GB`);
  if (usedStorage + REQUEST.bootVolumeSizeInGBs > LIMIT_STORAGE_GB) problems.push(`storage would be ${usedStorage + REQUEST.bootVolumeSizeInGBs} GB, the limit is ${LIMIT_STORAGE_GB} GB`);
} catch (error) {
  if (error.transient) return handleTransient(error);
  problems.push(`could not list existing resources: ${error.message}`);
}

if (problems.length) {
  // A refusal stops the claimer until its static data is reset; it is never retried.
  data.stopped = true;
  inc('costGuardRefusals');
  data.metrics = { ...metrics, counters };
  data.lifetime = lifetime;
  return [{ json: { kind: 'failure', title: 'Cost guard refused the A1 launch', body: [...problems, used, 'The claimer has stopped.'].filter(Boolean).join('\n'), url: '' } }];
}
data.metrics = { ...metrics, counters };
data.lifetime = lifetime;
return [{ json: { kind: '', title: '', body: '', url: '', request: REQUEST, knownInstanceIds } }];

// Launch instance: sign the launch request and send it. Runs only after the cost guard let it through.
const input = $input.first().json;
if (input.skipLaunch) return [{ json: input }];

const crypto = require('crypto');
const { request, knownInstanceIds = [] } = input;
const base = $env.HUNTER_OCI_API_BASE;
const target = '/20160918/instances';
// The Code node sandbox has no URL global, so take the host from the base URL by hand.
const host = base.replace(/^https?:\/\//, '').split('/')[0];
const keyId = [$env.HUNTER_OCI_TENANCY_OCID, $env.HUNTER_OCI_USER_OCID, $env.HUNTER_OCI_KEY_FINGERPRINT].join('/');
const key = $env.HUNTER_OCI_PRIVATE_KEY_PEM.replace(/\\n/g, '\n');

const body = JSON.stringify({
  availabilityDomain: $env.HUNTER_OCI_AVAILABILITY_DOMAIN,
  compartmentId: $env.HUNTER_OCI_COMPARTMENT_OCID,
  displayName: request.displayName,
  shape: request.shape,
  shapeConfig: { ocpus: request.ocpus, memoryInGBs: request.memoryInGBs },
  sourceDetails: { sourceType: 'image', imageId: $env.HUNTER_OCI_IMAGE_OCID, bootVolumeSizeInGBs: request.bootVolumeSizeInGBs },
  createVnicDetails: { subnetId: $env.HUNTER_OCI_SUBNET_OCID, assignPublicIp: true },
  metadata: { ssh_authorized_keys: $env.HUNTER_OCI_SSH_PUBLIC_KEY },
});
const date = new Date().toUTCString();
const digest = crypto.createHash('sha256').update(body).digest('base64');
const contentType = 'application/json';
const contentLength = String(Buffer.byteLength(body));
const signing = [
  `(request-target): post ${target}`,
  `date: ${date}`,
  `host: ${host}`,
  `x-content-sha256: ${digest}`,
  `content-type: ${contentType}`,
  `content-length: ${contentLength}`,
].join('\n');
const signature = crypto.sign('sha256', Buffer.from(signing), key).toString('base64');

let response;
try {
  response = await this.helpers.httpRequest({
    method: 'POST',
    url: base + target,
    headers: {
      date,
      'x-content-sha256': digest,
      'content-type': contentType,
      'content-length': contentLength,
      authorization: `Signature version="1",keyId="${keyId}",algorithm="rsa-sha256",headers="(request-target) date host x-content-sha256 content-type content-length",signature="${signature}"`,
    },
    body,
    timeout: 30000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
} catch (error) {
  return [{ json: { statusCode: 0, headers: {}, body: {}, networkError: error.message || 'network error', knownInstanceIds } }];
}
let responseBody = response.body;
try {
  if (typeof responseBody === 'string') responseBody = JSON.parse(responseBody);
} catch {
  // Keep the raw text when the body is not JSON.
}
return [{ json: { statusCode: response.statusCode, headers: response.headers, body: responseBody, knownInstanceIds } }];

// Read response: classify one launch response, update the claimer's counters and the wait before the next attempt, and pass on the message to send (if any).
const input = $input.first().json;
if (input.skipLaunch) {
  return [{ json: { outcome: input.outcome || 'verified', kind: input.kind || '', title: input.title || '', body: input.body || '', url: input.url || '' } }];
}

const { statusCode, body = {}, networkError = '', knownInstanceIds = [] } = input;
const headers = input.headers || {};
const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const counters = metrics.counters ?? {};
const lifetime = data.lifetime ?? {};
const rateLimit = data.rateLimit ?? {
  consecutive429: metrics.consecutive429 ?? 0,
  backoffLevel: Math.min(5, metrics.consecutive429 ?? 0),
  non429Streak: 0,
  currentWaitSeconds: metrics.currentWaitSeconds ?? 60,
};
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const message = typeof body === 'object' && body ? body.message ?? '' : '';
const requestId = headers['opc-request-id'] ?? '';

function inc(name) {
  counters[name] = (counters[name] ?? 0) + 1;
  lifetime[name] = (lifetime[name] ?? 0) + 1;
}

function parseRetryAfter(val) {
  if (val === undefined || val === null || val === '') return 0;
  const num = Number(val);
  if (Number.isFinite(num) && num >= 0) return Math.ceil(num);
  const parsed = Date.parse(String(val));
  if (Number.isFinite(parsed)) return Math.max(0, Math.ceil((parsed - Date.now()) / 1000));
  return 0;
}

function decayRateLimit() {
  rateLimit.consecutive429 = 0;
  rateLimit.non429Streak = (rateLimit.non429Streak ?? 0) + 1;
  if (rateLimit.non429Streak >= 2 && (rateLimit.backoffLevel ?? 0) > 0) {
    rateLimit.backoffLevel -= 1;
    rateLimit.non429Streak = 0;
  }
  const level = rateLimit.backoffLevel ?? 0;
  return level <= 1 ? 60 : Math.min(900, 60 * 2 ** (level - 2));
}

inc('attempts');

let outcome = 'error';
let wait = 60;
let notice = { kind: '', title: '', body: '', url: '' };

if (networkError || !statusCode) {
  outcome = 'unknown';
  inc('timeouts');
  data.pendingLaunch = { submittedAt: new Date().toISOString(), knownInstanceIds };
  wait = Math.max(60, rateLimit.currentWaitSeconds ?? 60);
} else {
  inc('responsesReceived');
  if ((statusCode === 200 || statusCode === 201) && body && body.id) {
    inc('acceptedLaunches');
    if (body.lifecycleState === 'RUNNING') {
      outcome = 'claimed';
      inc('success');
      inc('verifiedRunning');
      const nowIso = new Date().toISOString();
      data.claimed = { id: body.id, claimedAt: nowIso, verifiedAt: nowIso, lifecycleState: 'RUNNING' };
      notice = { kind: 'claim', title: `A1 VM created: ${body.displayName || 'vm-hunter-a1'}`, body: `Instance ${body.id}\n${body.shape}, ${body.shapeConfig?.ocpus} OCPU, ${body.shapeConfig?.memoryInGBs} GB\nAttempts: ${lifetime.attempts}`, url: '' };
    } else {
      outcome = 'accepted';
      data.pendingInstance = {
        id: body.id,
        displayName: body.displayName ?? 'vm-hunter-a1',
        shape: body.shape,
        shapeConfig: body.shapeConfig,
        acceptedAt: new Date().toISOString(),
        lifecycleState: body.lifecycleState ?? 'PROVISIONING',
      };
    }
  } else if (statusCode === 200 || statusCode === 201) {
    outcome = 'unknown';
    inc('errors');
    data.pendingLaunch = { submittedAt: new Date().toISOString(), knownInstanceIds };
    wait = Math.max(60, rateLimit.currentWaitSeconds ?? 60);
  } else if (statusCode === 500 && message.includes('Out of host capacity')) {
    outcome = 'capacity';
    inc('outOfCapacity');
    wait = decayRateLimit();
  } else if (statusCode === 429) {
    outcome = 'throttled';
    inc('rateLimited');
    rateLimit.consecutive429 = (rateLimit.consecutive429 ?? 0) + 1;
    rateLimit.backoffLevel = Math.min(5, (rateLimit.backoffLevel ?? 0) + 1);
    rateLimit.non429Streak = 0;
    const backoff = Math.min(900, 60 * 2 ** (rateLimit.backoffLevel - 1));
    const retryAfter = parseRetryAfter(headers['retry-after']);
    wait = Math.max(backoff, retryAfter);
    if (wait >= 900 && metrics.alerted?.capReached !== today) {
      metrics.alerted = { ...(metrics.alerted ?? {}), capReached: today };
      notice = { kind: 'alert', title: 'A1 claim at the 15-minute rate-limit wait', body: `Rate limited (HTTP 429, backoff level ${rateLimit.backoffLevel}/5). Waiting ${wait}s before next attempt.`, url: '' };
    }
  } else if ([400, 401, 403, 404].includes(statusCode)) {
    // Configuration or auth problem: retrying cannot fix it, so the claimer stops until its configuration is fixed.
    outcome = 'config';
    inc('configErrors');
    data.stopped = true;
    notice = { kind: 'failure', title: `A1 claim stopped: HTTP ${statusCode}`, body: `${body?.code ?? 'unknown'}: ${message}\nRequest id: ${requestId}\nThe claimer will not retry until its configuration is fixed.`, url: '' };
  } else {
    inc('errors');
    wait = decayRateLimit();
  }
}

rateLimit.currentWaitSeconds = wait;
data.rateLimit = rateLimit;
metrics.counters = counters;
metrics.day = metrics.day ?? today;
metrics.consecutive429 = rateLimit.consecutive429;
metrics.currentWaitSeconds = wait;
data.metrics = metrics;
data.lifetime = lifetime;
data.nextAttemptAt = Date.now() + wait * 1000;
return [{ json: { outcome, ...notice } }];

// Shape summary: build the 09:00 claimer summary line from the counters, then reset daily counters while preserving rateLimit and lifetime telemetry.
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const c = metrics.counters ?? {};
const state = data.claimed ? 'claimed' : data.stopped ? 'stopped' : data.pendingInstance ? 'verifying' : 'hunting';
const line = `Claimer · ${c.attempts ?? 0} attempts · ${c.outOfCapacity ?? 0} out of capacity · ${c.rateLimited ?? 0} rate limited · ${c.errors ?? 0} errors · ${c.costGuardRefusals ?? 0} cost guard refusals · ${state}`;
const rateLimit = data.rateLimit ?? { consecutive429: metrics.consecutive429 ?? 0, backoffLevel: Math.min(5, metrics.consecutive429 ?? 0), non429Streak: 0, currentWaitSeconds: metrics.currentWaitSeconds ?? 60 };
data.rateLimit = rateLimit;
data.metrics = {
  day: today,
  counters: {},
  alerted: metrics.alerted ?? {},
  consecutive429: rateLimit.consecutive429,
  currentWaitSeconds: rateLimit.currentWaitSeconds,
};
return [{ json: { kind: 'summary', title: `Claimer summary (${metrics.day ?? today})`, body: line, url: '' } }];
